import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.Files;
import java.util.HashMap;
import java.util.Map;
import java.io.IOException;
import java.util.stream.Stream;

public class AdvancedFileProcessor {
    private Path directoryPath;

    public AdvancedFileProcessor(String directoryPath) {
        this.directoryPath = Paths.get(directoryPath);
        if (!Files.isDirectory(this.directoryPath)) {
            throw new IllegalArgumentException("Provided path is not a directory");
        }
    }

    public Map<String, Object> processFiles() {
        Map<String, Object> result = new HashMap<>();
        int fileCount = 0;
        long totalSize = 0L;

        try (Stream<Path> paths = Files.walk(directoryPath)) {
            for (Path path : (Iterable<Path>) paths::iterator) {
                if (Files.isRegularFile(path)) {
                    fileCount++;
                    totalSize += Files.size(path);
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

        result.put("fileCount", fileCount);
        result.put("totalSize", totalSize);
        result.put("largestFile", "");
        result.put("wordFrequency", new HashMap<String, Integer>());
        return result;
    }
}

