            result.add(node.data);
            inOrderRec(node.right, result);
        }
    }
}

class AdvancedTreeLoader {
    public static <T extends Comparable<T>> void load(BinaryTree<T> tree, List<T> data, boolean shouldSort) {
        if (shouldSort) {
            List<T> sortedData = new ArrayList<>(data);
            Collections.sort(sortedData);
            loadBalanced(tree, sortedData, 0, sortedData.size() - 1);
        } else {
            for (T item : data) {
                tree.insert(item);
            }
        }
    }

    private static <T extends Comparable<T>> void loadBalanced(BinaryTree<T> tree, List<T> sortedData, int start, int end) {
        if (start > end) {
            return;
        }

        int mid = start + (end - start) / 2;
        tree.insert(sortedData.get(mid));

        loadBalanced(tree, sortedData, start, mid - 1);
        loadBalanced(tree, sortedData, mid + 1, end);
    }
}

