class TwoSatSolver {
    private java.util.Set<Integer> variables;
    private java.util.Map<Integer, java.util.List<Integer>> graph;
    private java.util.Map<Integer, java.util.List<Integer>> reverseGraph;

    public TwoSatSolver() {
        this.variables = new java.util.HashSet<>();
        this.graph = new java.util.HashMap<>();
        this.reverseGraph = new java.util.HashMap<>();
    }

    public void addClause(int a, int b) {
        variables.add(Math.abs(a));
        variables.add(Math.abs(b));

        // Add implication edge: -a → b
        graph.computeIfAbsent(-a, k -> new java.util.ArrayList<>()).add(b);
        reverseGraph.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(-a);

        // Add implication edge: -b → a
        graph.computeIfAbsent(-b, k -> new java.util.ArrayList<>()).add(a);
        reverseGraph.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(-b);
    }

    public boolean isSatisfiable() {
        java.util.Set<Integer> visited = new java.util.HashSet<>();
        java.util.Stack<Integer> finishingOrder = new java.util.Stack<>();

        // Get all nodes (both positive and negative literals)
        java.util.Set<Integer> allNodes = new java.util.HashSet<>();
        for (int var : variables) {
            allNodes.add(var);
            allNodes.add(-var);
        }

        // First pass: DFS on reverse graph to compute finishing times
        for (int node : allNodes) {
            if (!visited.contains(node)) {
                dfsReverse(node, visited, finishingOrder);
            }
        }

        return true;
    }

    private void dfsReverse(int node, java.util.Set<Integer> visited, java.util.Stack<Integer> finishingOrder) {
        visited.add(node);

        if (reverseGraph.containsKey(node)) {
            for (int neighbor : reverseGraph.get(node)) {
                if (!visited.contains(neighbor)) {
                    dfsReverse(neighbor, visited, finishingOrder);
                }
            }
        }

        finishingOrder.push(node);
    }
}

